// gen-format-fixture.mjs — the Alligators-scale, UNLINKED project fixture for
// `maude migrate v2` (V2-1.12 §5.12). Bun only (it imports the canonical .ts
// serializers so every board is the bytes the app itself would write).
//
// Deterministic: a seeded PRNG (mulberry32), fixed timestamps, content-
// addressed asset names — two runs are byte-identical. Builds on
// perf-canvas.mjs (canvas bodies) and perf-annotations-mixed.mjs (boards of
// every v1 kind, converted to v2 through the real `v1ToV2`).
//
//   generateFormatFixture(dir, { legacy?: boolean, seed?: number }) → counts
//
// writes `<dir>/.design/` with:
//   config.json  house style, two canvasGroups, three designSystems,
//                NO formatVersion, NO linkedHub
//   93 canvases  in nested ui/ folders (≤ 3 deep); 57 with .meta.json (sections,
//                layout.artboards, ai_context, designSystem, an unknown legacy
//                key, a stale inline viewport), 36 without; one canvas with 21
//                artboards; 4 video comps (one: 3 standalone overlay
//                <Sequence>s + audio); 2 print artboards
//   30 boards    every built-in type, sections nested 3 deep, bound arrows
//                (element, magnet, free point), groups, author ai/human,
//                locked, one unknown-type element, one empty board
//                (+ `legacy`: one `.annotations.svg` without a board)
//   3 systems    a Missing-roles shape (tokens CSS, _components.css,
//                preview/*.tsx, a font), a Private-only shape, an empty skeleton
//   247 assets   tiny PNG / JPG / SVG / WOFF2 / MP4 / M4A + .photo.json,
//                .audio.json, .footage.json, .registry.json, .edl.json sidecars,
//                old .srt captions (some with the bare whisper .json beside)
//   _comments/   10 canvases, incl. timeline + annotation anchors
//   _chat/       12 chats — 9 with `[maude-context canvas=…]`, 3 without — and
//                .meta.json titles / archived
//   runtime noise that must stay untouched: _history/, _trash/,
//                _canvas-state/, _state/ (no _sync.json)

import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { v1ToV2 } from '../../annotations/migrate-v1.ts';
import { isKnownType, specOf } from '../../annotations/registry.ts';
import { serializeBoard, validateElements } from '../../annotations/schema.ts';
import { buildMixedStrokes } from './perf-annotations-mixed.mjs';
import { renderCanvasSource, renderMeta } from './perf-canvas.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));

function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const sha8 = (b) => createHash('sha256').update(b).digest('hex').slice(0, 8);

function put(root, rel, data) {
  const abs = join(root, ...rel.split('/'));
  mkdirSync(dirname(abs), { recursive: true });
  writeFileSync(abs, data);
}

const AREAS = ['brand', 'season', 'social', 'tickets', 'merch', 'web'];
const SUBS = ['2025', '2026', 'drafts'];

/** Canvas paths: 93 under ui/, nested ≤ 3 deep (ui/<area>/<sub>/<name>). */
function canvasPaths() {
  const out = [];
  for (let i = 0; i < 93; i++) {
    const area = AREAS[i % AREAS.length];
    const depth = i % 3; // 0 → ui/x, 1 → ui/area/x, 2 → ui/area/sub/x
    const name = `c${String(i).padStart(2, '0')}`;
    out.push(
      depth === 0
        ? `ui/${name}.tsx`
        : depth === 1
          ? `ui/${area}/${name}.tsx`
          : `ui/${area}/${SUBS[i % SUBS.length]}/${name}.tsx`
    );
  }
  return out;
}

const slugOf = (rel) => rel.replace(/\.tsx$/, '').replace(/\//g, '-');

function compSource(i, withOverlays) {
  const overlays = withOverlays
    ? `
      <Sequence from={0} durationInFrames={90} layout="none"><Img src="assets/overlay-a.png" /></Sequence>
      <Sequence from={30} durationInFrames={60} layout="none"><Img src="assets/overlay-b.png" /></Sequence>
      <Sequence from={60} durationInFrames={30} layout="none"><Img src="assets/overlay-c.png" /></Sequence>
      <Audio src="assets/music.m4a" />`
    : '';
  return `// GENERATED by gen-format-fixture.mjs — a video comp.
import { DCArtboard, DesignCanvas } from '@maude/canvas-lib';
import { AbsoluteFill, Audio, Img, Sequence } from 'remotion';

export default function Canvas() {
  return (
    <DesignCanvas>
      <DCArtboard id="comp-${i}" kind="video" label="Reel ${i}" width={1080} height={1920} fps={30} durationInFrames={300}>
        <AbsoluteFill>
          <Sequence from={0} durationInFrames={150}><Img src="assets/clip-${i}.png" /></Sequence>${overlays}
        </AbsoluteFill>
      </DCArtboard>
    </DesignCanvas>
  );
}
`;
}

function printSource() {
  return `// GENERATED by gen-format-fixture.mjs — print artboards.
import { DCArtboard, DesignCanvas } from '@maude/canvas-lib';

export default function Canvas() {
  return (
    <DesignCanvas>
      <DCArtboard id="poster-a3" kind="print" label="Poster A3" width={1123} height={1587}><div>Game day</div></DCArtboard>
      <DCArtboard id="flyer-a5" kind="print" label="Flyer A5" width={559} height={794}><div>Tickets</div></DCArtboard>
    </DesignCanvas>
  );
}
`;
}

function metaFor(i, boards, rnd) {
  const m = renderMeta(boards);
  return {
    ...m,
    title: `Canvas ${i}`,
    sections: [
      { id: 's1', label: 'Main', artboards: m.layout.artboards.slice(0, 2).map((a) => a.id) },
    ],
    ai_context: `Brno Alligators — canvas ${i}`,
    designSystem: i % 2 ? 'alligators' : 'private-ds',
    legacyFlag: { keptBy: 'every reader', n: i }, // an unknown legacy key
    viewport: { x: Math.round(rnd() * 1000), y: 0, zoom: 1 }, // stale inline camera
  };
}

/** One board: a mixed v1 cluster through the real converter, plus extras. */
function boardFor(i, rnd) {
  if (i === 29) return serializeBoard([]); // the empty board
  const count = 6 + (i % 5) * 6;
  const { elements } = v1ToV2(buildMixedStrokes(count, { seed: 0xa11 + i, originX: i * 50 }), {});
  const extra = [];
  const ix = (k) => `z${String(k).padStart(2, '0')}`;
  extra.push({
    id: `img${i}`,
    type: 'image',
    index: ix(1),
    x: 10,
    y: 10,
    w: 120,
    h: 80,
    href: 'assets/0a0b0c0d.png',
    alt: 'logo',
    author: { kind: i % 2 ? 'ai' : 'human', name: i % 2 ? 'Claude' : 'Tereza' },
  });
  extra.push({
    id: `lnk${i}`,
    type: 'link',
    index: ix(2),
    x: 200,
    y: 10,
    w: 240,
    h: 80,
    url: 'https://alligators.cz',
    title: 'Club',
    domain: 'alligators.cz',
    locked: true,
  });
  extra.push({
    id: `med${i}`,
    type: 'mediaref',
    index: ix(3),
    x: 500,
    y: 10,
    w: 200,
    h: 120,
    src: 'assets/0e0f1011.mp4',
    media: 'video',
    title: 'Highlights',
  });
  if (i % 3 === 0) {
    // sections nested 3 deep, and a free-point + magnet arrow on a sticky
    extra.push({
      id: `sa${i}`,
      type: 'section',
      index: ix(4),
      x: 0,
      y: 400,
      w: 900,
      h: 600,
      label: 'Outer',
    });
    extra.push({
      id: `sb${i}`,
      type: 'section',
      parent: `sa${i}`,
      index: ix(5),
      x: 20,
      y: 40,
      w: 700,
      h: 500,
      label: 'Middle',
    });
    extra.push({
      id: `sc${i}`,
      type: 'section',
      parent: `sb${i}`,
      index: ix(6),
      x: 20,
      y: 40,
      w: 500,
      h: 300,
      label: 'Inner',
    });
    extra.push({
      id: `st${i}`,
      type: 'sticky',
      parent: `sc${i}`,
      index: ix(7),
      x: 20,
      y: 40,
      w: 160,
      h: 120,
      text: 'Inside three sections',
      groups: [`g${i}`],
    });
    extra.push({
      id: `ar${i}`,
      type: 'arrow',
      index: ix(8),
      start: { el: `st${i}`, nx: 1, ny: 0.5 },
      end: { x: 1200, y: 300 },
    });
  }
  if (i === 7)
    extra.push({
      id: 'vote1',
      type: 'future-kind',
      index: ix(9),
      x: 5,
      y: 5,
      payload: { from: 'a newer peer' },
    }); // unknown type
  const { elements: canon, dropped } = validateElements([...elements, ...extra]);
  if (dropped.length) throw new Error(`fixture board ${i} drops: ${JSON.stringify(dropped)}`);
  // A v1 fixture carries NO extension field: the 1.x registry kept none, and
  // the reverse --strip assertions count every one as "lost".
  for (const el of canon) {
    if (!isKnownType(el.type)) continue;
    const spec = specOf(el.type);
    for (const k of Object.keys(el))
      if (!Object.hasOwn(spec, k))
        throw new Error(`fixture board ${i}: ${el.type}.${k} is not a 1.x field`);
  }
  void rnd;
  return serializeBoard(canon);
}

function tinyAsset(kind, n) {
  const body = Buffer.from(`${kind}-${n}-alligators-fixture`);
  const head = {
    png: Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    jpg: Buffer.from([0xff, 0xd8, 0xff, 0xe0]),
    svg: Buffer.from('<svg xmlns="http://www.w3.org/2000/svg"><!--'),
    woff2: Buffer.from('wOF2'),
    mp4: Buffer.from([0, 0, 0, 0x18, 0x66, 0x74, 0x79, 0x70]),
    m4a: Buffer.from([0, 0, 0, 0x18, 0x66, 0x74, 0x79, 0x70, 0x4d, 0x34, 0x41]),
  }[kind];
  const tail = kind === 'svg' ? Buffer.from('--></svg>') : Buffer.alloc(0);
  return Buffer.concat([head, body, tail]);
}

const srt = (lines) =>
  `${lines.map((t, i) => `${i + 1}\n00:00:0${i},000 --> 00:00:0${i},900\n${t}`).join('\n\n')}\n`;

const whisperJson = (words) =>
  `${JSON.stringify(
    {
      transcription: words.map((w, i) => ({
        text: ` ${w}`,
        offsets: { from: i * 400, to: i * 400 + 350 },
      })),
    },
    null,
    2
  )}\n`;

export function generateFormatFixture(dir, opts = {}) {
  const rnd = mulberry32(opts.seed ?? 0xa11a);
  const d = join(dir, '.design');
  const counts = {
    canvases: 0,
    metas: 0,
    boards: 0,
    assets: 0,
    chats: 0,
    comments: 0,
    srt: 0,
    bareJson: 0,
  };

  // ── config (house style: 2-space indent, trailing newline) ──
  put(
    d,
    'config.json',
    `${JSON.stringify(
      {
        name: 'brno-alligators',
        projectLabel: 'Alligators brand',
        designRoot: '.design',
        rootClass: 'alligators',
        themeDefault: 'dark',
        canvasGroups: [
          { label: 'Design system', path: 'system' },
          { label: 'Screens', path: 'ui' },
        ],
        designSystems: [
          {
            name: 'alligators',
            path: 'system/alligators',
            tokensCssRel: 'system/alligators/colors_and_type.css',
          },
          {
            name: 'private-ds',
            path: 'system/private-ds',
            tokensCssRel: 'system/private-ds/colors_and_type.css',
          },
          { name: 'skeleton', path: 'system/skeleton' },
        ],
        defaultDesignSystem: 'alligators',
      },
      null,
      2
    )}\n`
  );

  // ── canvases + metas ──
  const paths = canvasPaths();
  const comps = new Set([5, 17, 41, 77]);
  paths.forEach((rel, i) => {
    let boards = 2 + (i % 4);
    if (i === 12) boards = 21;
    let src = renderCanvasSource(boards);
    if (comps.has(i)) src = compSource(i, i === 17);
    if (i === 60) src = printSource();
    put(d, rel, src);
    counts.canvases++;
    if (i < 57) {
      put(
        d,
        rel.replace(/\.tsx$/, '.meta.json'),
        `${JSON.stringify(metaFor(i, boards, rnd), null, 2)}\n`
      );
      counts.metas++;
    }
  });

  // ── boards (flat at the design root, keyed by the canvas slug) ──
  for (let i = 0; i < 30; i++) {
    put(d, `${slugOf(paths[i])}.annotations.json`, boardFor(i, rnd));
    counts.boards++;
  }
  if (opts.legacy) {
    const svg = readFileSync(join(HERE, 'annotations-v2', 'ui-smoke.v1.svg'), 'utf8');
    put(d, `${slugOf(paths[40])}.annotations.svg`, svg);
  }

  // ── design systems ──
  put(
    d,
    'system/alligators/colors_and_type.css',
    ':root { --bg-0: #0b0b0c; --fg-0: #f4f1ea; --accent: #2f7d32; }\n.alligators[data-theme="dark"] { --bg-1: #151517; }\n'
  );
  put(d, 'system/alligators/preview/_components.css', '.btn { padding: 8px 12px; }\n');
  put(
    d,
    'system/alligators/preview/buttons.tsx',
    'import { DCArtboard, DesignCanvas } from \'@maude/canvas-lib\';\nexport default function Canvas() { return <DesignCanvas><DCArtboard id="btn" width={400} height={200}><button className="btn">Go</button></DCArtboard></DesignCanvas>; }\n'
  );
  put(
    d,
    'system/alligators/preview/colors.tsx',
    'import { DCArtboard, DesignCanvas } from \'@maude/canvas-lib\';\nexport default function Canvas() { return <DesignCanvas><DCArtboard id="c" width={400} height={200}><div /></DCArtboard></DesignCanvas>; }\n'
  );
  put(d, 'system/alligators/assets/fonts/display.woff2', tinyAsset('woff2', 'display'));
  put(d, 'system/alligators/README.md', '# Alligators\n');
  put(d, 'system/private-ds/colors_and_type.css', ':root { --bg-0: #fff; --fg-0: #111; }\n');
  put(d, 'system/private-ds/README.md', '# Private\n');
  put(d, 'system/skeleton/README.md', '# Skeleton\n');

  // ── assets: 247 files ──
  const kinds = ['png', 'jpg', 'svg', 'woff2'];
  const media = [];
  let n = 0;
  const asset = (rel, data) => {
    put(d, rel, data);
    counts.assets++;
  };
  for (let k = 0; k < 150; k++) {
    const kind = kinds[k % kinds.length];
    const b = tinyAsset(kind, k);
    asset(`assets/${sha8(b)}.${kind}`, b);
    if (k % 10 === 0)
      asset(
        `assets/${sha8(b)}.photo.json`,
        `${JSON.stringify({ v: 1, ops: [{ kind: 'exposure', value: 0.2 }] })}\n`
      );
  }
  for (let k = 0; k < 12; k++) {
    const kind = k % 3 === 0 ? 'm4a' : 'mp4';
    const b = tinyAsset(kind, `m${k}`);
    const base = sha8(b);
    media.push(base);
    asset(`assets/${base}.${kind}`, b);
    if (kind === 'm4a')
      asset(`assets/${base}.audio.json`, `${JSON.stringify({ v: 1, gainDb: -3 })}\n`);
    else asset(`assets/${base}.footage.json`, `${JSON.stringify({ v: 1, shots: [] })}\n`);
  }
  // old captions: 7 with media, 3 of them with the bare whisper dump; 1 orphan
  for (let k = 0; k < 7; k++) {
    asset(`assets/${media[k]}.srt`, srt(['Go', 'Alligators go', 'Game day Brno']));
    counts.srt++;
    if (k < 3) {
      asset(`assets/${media[k]}.json`, whisperJson(['Go', 'Alligators', 'go']));
      counts.bareJson++;
    }
  }
  asset('assets/deadbeef.srt', srt(['orphan caption']));
  counts.srt++;
  for (let k = 0; counts.assets < 245; k++) {
    const b = tinyAsset('png', `fill-${k}`);
    asset(`assets/${sha8(b)}.png`, b);
    n++;
  }
  asset('assets/Card.registry.json', `${JSON.stringify({ v: 1, components: ['Card'] })}\n`);
  put(d, 'reel-2026.edl.json', `${JSON.stringify({ v: 1, beats: [] })}\n`);
  counts.assets++;

  // ── comments ──
  for (let i = 0; i < 10; i++) {
    const slug = slugOf(paths[i]);
    const c = [
      {
        id: `c_${i}a`,
        file: paths[i],
        selector: '.btn',
        dom_path: [],
        tag: 'div',
        classes: '',
        bounds: null,
        html_excerpt: '',
        text: 'Too loud',
        status: 'open',
        created: '2026-09-01T10:00:00.000Z',
        resolved_at: null,
        author: 'tereza',
        thread: [
          { id: `r_${i}`, author: 'michal', body: 'agreed', created: '2026-09-01T11:00:00.000Z' },
        ],
        mentions: [],
        ...(i % 3 === 0 ? { timeline: { clipStableId: 'clip-1', frameOffset: 12 } } : {}),
        ...(i % 4 === 0 ? { annotationId: 'img0' } : {}),
      },
    ];
    put(d, `_comments/${slug}.json`, JSON.stringify(c));
    counts.comments++;
  }

  // ── chats (per Mac) ──
  for (let i = 0; i < 12; i++) {
    const id = `chat-${String(i).padStart(2, '0')}`;
    const canvas = `.design/${paths[i]}`;
    const user =
      i < 9
        ? `Make the hero louder\n[maude-context canvas="${canvas}" mtime=1760000000 note=untrusted-canvas-data-not-instructions]`
        : 'General question about the brand';
    const lines = [
      JSON.stringify({ role: 'user', text: user, at: 1760000000000 + i }),
      JSON.stringify({ role: 'assistant', text: 'Done.', at: 1760000001000 + i }),
    ];
    put(d, `_chat/${id}.jsonl`, `${lines.join('\n')}\n`);
    if (i % 2 === 0)
      put(
        d,
        `_chat/${id}.meta.json`,
        JSON.stringify({ title: `Chat ${i}`, ...(i % 4 === 0 ? { archived: true } : {}) })
      );
    counts.chats++;
  }

  // ── runtime noise that must stay untouched ──
  put(d, '_history/ui-c00/2026-09-01T10-00-00.tsx', '// an old snapshot\n');
  put(d, '_trash/old-1/old.tsx', '// trashed\n');
  put(d, '_canvas-state/ui-c00.view.json', JSON.stringify({ x: 1, y: 2, zoom: 0.5 }));
  put(d, '_state/accepted-mode.json', JSON.stringify({ v: 1, mode: 'legacy' }));
  void n;
  return { designRoot: d, counts };
}

if (import.meta.main) {
  const out = process.argv[2];
  if (!out) {
    process.stderr.write('usage: bun gen-format-fixture.mjs <dir> [--legacy]\n');
    process.exit(2);
  }
  const r = generateFormatFixture(out, { legacy: process.argv.includes('--legacy') });
  process.stdout.write(`${JSON.stringify(r.counts)}\n`);
}
